"""Listen for and periodically dump occupancy maps generated by SLAM Toolbox.

Every received ``nav_msgs/msg/OccupancyGrid`` message is counted as one map
update. By default, updates 10, 20, 30, and so on are written as a portable
graymap (``.pgm``) plus a matching map-server metadata file (``.yaml``).
The latest sensor and transform inputs are saved beside each map as a JSON
snapshot.
"""

import json
from pathlib import Path

import rclpy
from nav_msgs.msg import Odometry
from nav_msgs.msg import OccupancyGrid
from rclpy.node import Node
from rclpy.qos import DurabilityPolicy, QoSProfile, ReliabilityPolicy
from sensor_msgs.msg import LaserScan
from tf2_msgs.msg import TFMessage


class MapListener(Node):
    """Report map updates and save every Nth map to disk.

    Parameters:
        dump_every_n_maps (int): Save one map after this many received map
            messages. Defaults to ``10``.
        dump_directory (str): Directory for dumped ``.pgm`` and ``.yaml``
            files and input snapshots. Relative paths are resolved from the
            process working directory. Defaults to ``maps``.
    """

    def __init__(self):
        """Create the map subscription and initialize change tracking."""
        super().__init__('map_listener')

        # Keep the dump policy configurable so the same node can be used for
        # quick tests (for example, every map) or longer runs (every 100 maps).
        self.declare_parameter('dump_every_n_maps', 10)
        self.declare_parameter('dump_directory', 'maps')
        self.dump_every_n_maps = self.get_parameter('dump_every_n_maps').value
        if self.dump_every_n_maps < 1:
            raise ValueError('dump_every_n_maps must be greater than zero')

        configured_directory = Path(
            str(self.get_parameter('dump_directory').value)
        ).expanduser()
        self.dump_directory = (
            configured_directory
            if configured_directory.is_absolute()
            else Path.cwd() / configured_directory
        )

        # SLAM Toolbox publishes the current occupancy grid on `/map`.
        self.subscription = self.create_subscription(
            OccupancyGrid,
            '/map',
            self.on_map,
            10,
        )
        # Cache the most recent inputs that contributed to the map stream.
        # They are serialized alongside every tenth map update.
        self.scan_subscription = self.create_subscription(
            LaserScan,
            '/scan',
            self.on_scan,
            10,
        )
        self.odom_subscription = self.create_subscription(
            Odometry,
            '/odom',
            self.on_odom,
            10,
        )
        self.tf_subscription = self.create_subscription(
            TFMessage,
            '/tf',
            self.on_tf,
            10,
        )
        static_tf_qos = QoSProfile(
            depth=1,
            reliability=ReliabilityPolicy.RELIABLE,
            durability=DurabilityPolicy.TRANSIENT_LOCAL,
        )
        self.static_tf_subscription = self.create_subscription(
            TFMessage,
            '/tf_static',
            self.on_static_tf,
            static_tf_qos,
        )
        self.last_map_shape = None
        self.map_count = 0
        self.latest_scan = None
        self.latest_odom = None
        self.latest_tf = None
        self.latest_static_tf = None

    def on_map(self, message):
        """Log the dimensions and resolution of each new map shape.

        Args:
            message: Occupancy grid published by SLAM Toolbox.
        """
        # Count every callback, even when the map dimensions have not changed.
        # SLAM Toolbox can publish successive updates with the same dimensions.
        self.map_count += 1
        shape = (message.info.width, message.info.height)

        # Avoid repeating identical shape lines while still reporting when
        # SLAM expands or changes the map geometry.
        if shape != self.last_map_shape:
            self.get_logger().info(
                f'Received map: {message.info.width} x {message.info.height} '
                f'cells, resolution {message.info.resolution:.3f} m/cell'
            )
            self.last_map_shape = shape

        # Dump maps 10, 20, 30, ... by default. The modulo check deliberately
        # uses the callback count rather than map dimensions or timestamps.
        if self.map_count % self.dump_every_n_maps == 0:
            self.dump_map(message, self.map_count)

    def on_scan(self, message):
        """Cache the latest laser scan used by the SLAM pipeline."""
        self.latest_scan = message

    def on_odom(self, message):
        """Cache the latest odometry message used by the SLAM pipeline."""
        self.latest_odom = message

    def on_tf(self, message):
        """Cache the latest dynamic TF message used by the SLAM pipeline."""
        self.latest_tf = message

    def on_static_tf(self, message):
        """Cache the latest static TF message used by the sensor pipeline."""
        self.latest_static_tf = message

    def dump_map(self, message, map_number):
        """Write one occupancy grid as PGM image and YAML metadata.

        Args:
            message: Occupancy grid to serialize.
            map_number: One-based received-map count used in output names.

        The PGM uses standard map-server grayscale values: occupied cells are
        black (0), free cells are white (254), and unknown cells are gray
        (205). The YAML file stores the resolution and origin needed to load
        the image back as a ROS map.
        """
        width = message.info.width
        height = message.info.height
        expected_cells = width * height
        if len(message.data) != expected_cells:
            self.get_logger().error(
                f'Cannot dump map {map_number}: expected {expected_cells} '
                f'cells, received {len(message.data)}'
            )
            return

        self.dump_directory.mkdir(parents=True, exist_ok=True)
        stem = f'map_{map_number:06d}'
        image_path = self.dump_directory / f'{stem}.pgm'
        yaml_path = self.dump_directory / f'{stem}.yaml'

        # OccupancyGrid data is row-major from the bottom of the map, while
        # PGM image rows are conventionally written from top to bottom.
        pixels = bytearray()
        for row in range(height - 1, -1, -1):
            start = row * width
            for occupancy in message.data[start:start + width]:
                if occupancy < 0:
                    pixels.append(205)  # Unknown.
                elif occupancy >= 65:
                    pixels.append(0)  # Occupied.
                else:
                    pixels.append(254)  # Free.

        with image_path.open('wb') as image_file:
            image_file.write(f'P5\n{width} {height}\n255\n'.encode('ascii'))
            image_file.write(pixels)

        origin = message.info.origin
        yaml_path.write_text(
            f'image: {image_path.name}\n'
            f'resolution: {message.info.resolution}\n'
            f'origin: [{origin.position.x}, {origin.position.y}, 0.0]\n'
            'negate: 0\n'
            'occupied_thresh: 0.65\n'
            'free_thresh: 0.196\n'
            'mode: trinary\n'
        )

        self.get_logger().info(
            f'Dumped map {map_number} to {image_path} and {yaml_path}'
        )
        self.dump_input_snapshot(map_number)

    def dump_input_snapshot(self, map_number):
        """Save the latest scan, odometry, and TF inputs as JSON.

        The snapshot is taken when the corresponding map update is received.
        It contains the complete laser range array plus the message metadata,
        odometry pose/twist, and all transforms most recently received on
        ``/tf`` and ``/tf_static``.

        Args:
            map_number: One-based received-map count used in the output name.
        """
        snapshot = {
            'map_number': map_number,
            'scan': self.serialize_scan(self.latest_scan),
            'odom': self.serialize_odom(self.latest_odom),
            'tf': self.serialize_tf_message(self.latest_tf),
            'tf_static': self.serialize_tf_message(self.latest_static_tf),
        }
        input_path = self.dump_directory / f'map_{map_number:06d}_inputs.json'
        input_path.write_text(json.dumps(snapshot, indent=2) + '\n')
        self.get_logger().info(f'Dumped map inputs to {input_path}')

    @staticmethod
    def serialize_stamp(stamp):
        """Convert a ROS time message to a JSON-compatible dictionary."""
        return {'sec': stamp.sec, 'nanosec': stamp.nanosec}

    @classmethod
    def serialize_scan(cls, message):
        """Convert a LaserScan message to JSON, or return null if unavailable."""
        if message is None:
            return None
        return {
            'header': {
                'stamp': cls.serialize_stamp(message.header.stamp),
                'frame_id': message.header.frame_id,
            },
            'angle_min': message.angle_min,
            'angle_max': message.angle_max,
            'angle_increment': message.angle_increment,
            'time_increment': message.time_increment,
            'scan_time': message.scan_time,
            'range_min': message.range_min,
            'range_max': message.range_max,
            'ranges': list(message.ranges),
            'intensities': list(message.intensities),
        }

    @classmethod
    def serialize_odom(cls, message):
        """Convert an Odometry message to JSON, or return null if unavailable."""
        if message is None:
            return None
        pose = message.pose.pose
        twist = message.twist.twist
        return {
            'header': {
                'stamp': cls.serialize_stamp(message.header.stamp),
                'frame_id': message.header.frame_id,
            },
            'child_frame_id': message.child_frame_id,
            'pose': {
                'position': {
                    'x': pose.position.x,
                    'y': pose.position.y,
                    'z': pose.position.z,
                },
                'orientation': {
                    'x': pose.orientation.x,
                    'y': pose.orientation.y,
                    'z': pose.orientation.z,
                    'w': pose.orientation.w,
                },
            },
            'twist': {
                'linear': {
                    'x': twist.linear.x,
                    'y': twist.linear.y,
                    'z': twist.linear.z,
                },
                'angular': {
                    'x': twist.angular.x,
                    'y': twist.angular.y,
                    'z': twist.angular.z,
                },
            },
        }

    @classmethod
    def serialize_tf_message(cls, message):
        """Convert a TFMessage and all transforms to JSON."""
        if message is None:
            return None
        return [
            {
                'header': {
                    'stamp': cls.serialize_stamp(transform.header.stamp),
                    'frame_id': transform.header.frame_id,
                },
                'child_frame_id': transform.child_frame_id,
                'translation': {
                    'x': transform.transform.translation.x,
                    'y': transform.transform.translation.y,
                    'z': transform.transform.translation.z,
                },
                'rotation': {
                    'x': transform.transform.rotation.x,
                    'y': transform.transform.rotation.y,
                    'z': transform.transform.rotation.z,
                    'w': transform.transform.rotation.w,
                },
            }
            for transform in message.transforms
        ]


def main(args=None):
    """Run the map listener until interrupted."""
    rclpy.init(args=args)
    node = MapListener()
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        rclpy.shutdown()
